    ,{"name":"Серик Рузагул","school":"Иртышск","grade":"11","office":"Торайгырова","lang":"каз","groups":[{"code":"11 КТС-4","subject":"МАТ САУАТ"},{"code":"11 КТИ-3","subject":"ҚАЗ ТАРИХ"},{"code":"11 КТГ-1","subject":"ГЕОГРАФИЯ"},{"code":"11 КТБ-2","subject":"БИОЛОГИЯ"}],"student_phone":"87058384150","parent_phone":"87 776 243 309","contract":"Т070626/001","parent_name":"Исаханова Алмагуль","note":"НОВЫЙ"}
