    ,{"name":"Бауыржан Алинур","school":"Бокейхана","grade":"11","office":"Торайгырова","lang":"каз","groups":[{"code":"11 КТС-4","subject":"МАТ САУАТ"},{"code":"11 КТИ-3","subject":"ҚАЗ ТАРИХ"},{"code":"11 КТМ-3","subject":"МАТЕМ"},{"code":"11 КТФ-1","subject":"ФИЗИКА"}],"student_phone":"87081306874","parent_phone":"87753690963","contract":"Т140826/002","parent_name":"Жанибекова Булбул","note":"НОВЫЙ"}
    ,{"name":"Жармагамбет Аружан","school":"Алгабас","grade":"11","office":"Торайгырова","lang":"каз","groups":[{"code":"11 КТФ-2","subject":"ФИЗИКА"}],"student_phone":"87071385722 - вп / 87711241510 - звонки","parent_phone":"7 707 912 7497","contract":"T030926/002","parent_name":"Жармагамбетова Карлыгаш","note":""}
  ]'::jsonb;
begin
  for v_student in select * from jsonb_array_elements(v_students)
  loop
    begin
      -- ---------- ученик: найти или создать ----------
      select id into v_existing_id from students
      where archived = false and lower(trim(full_name)) = lower(trim(v_student->>'name'))
      limit 1;

      if v_existing_id is not null then
        v_new_id := v_existing_id;
        v_students_matched := v_students_matched + 1;
      else
        insert into students(full_name, school, grade, office, lang, phone, parent_phone, parent_name, contract_no, note, archived)
        values (
          v_student->>'name', nullif(v_student->>'school',''), nullif(v_student->>'grade',''),
          v_student->>'office', nullif(v_student->>'lang',''), nullif(v_student->>'student_phone',''),
          nullif(v_student->>'parent_phone',''), nullif(v_student->>'parent_name',''),
          nullif(v_student->>'contract',''), nullif(v_student->>'note',''), false
        )
        returning id into v_new_id;
        v_students_created := v_students_created + 1;
      end if;

      -- ---------- группы этого ученика: найти или создать, затем привязать ----------
      for v_group in select * from jsonb_array_elements(v_student->'groups')
      loop
        -- Только группы ТЕКУЩЕГО центра (10.../11...). Всё остальное —
        -- чужой центр, группу здесь не создаём и не трогаем.
        if (v_group->>'code') !~ '^1[01]' then
          v_skipped_other_center := v_skipped_other_center + 1;
          v_skipped_other_center_list := v_skipped_other_center_list || (v_student->>'name') || ' -> ' || (v_group->>'code') || E'\n';
          continue;
        end if;

        select id into v_group_id from groups
        where archived = false
          and office = (v_student->>'office')
          and lower(trim(name)) = lower(trim(v_group->>'code'))
        limit 1;

        if v_group_id is not null then
          v_groups_matched := v_groups_matched + 1;
        else
          -- Язык — по второй букве кода после класса (10/11): К -> каз, Р -> рус.
          v_group_lang := case
            when (v_group->>'code') ~* '^\d{1,2}\s*[КкKk]' then 'каз'
            when (v_group->>'code') ~* '^\d{1,2}\s*[РрRr]' then 'рус'
            else v_student->>'lang'
          end;

          insert into groups(name, office, lang, subject_name, capacity, archived, note)
          values (
            trim(v_group->>'code'),
            v_student->>'office',
            v_group_lang,
            nullif(v_group->>'subject',''),
            13,
            false,
            -- тот же формат note = "<предмет> · <офис> · <язык>", что и при
            -- ручном создании группы через Управление -> Группы (Manage.jsx) —
            -- иначе группа не отобразится в фильтре того экрана
            trim(coalesce(v_group->>'subject','') || ' · ' || (v_student->>'office') || ' · ' || coalesce(v_group_lang,''))
          )
          returning id into v_group_id;
          v_groups_created := v_groups_created + 1;
        end if;

        insert into student_groups(student_id, group_id) values (v_new_id, v_group_id)
        on conflict do nothing;
        v_links_created := v_links_created + 1;
      end loop;
    exception when others then
      v_errors := v_errors + 1;
      v_error_list := v_error_list || (v_student->>'name') || ': ' || sqlerrm || E'\n';
    end;
  end loop;

  raise notice E'=== СИНХРОНИЗАЦИЯ УЧЕНИКОВ И ГРУПП (сентябрь 2026) ===\nСоздано учеников: %\nНайдено существующих учеников: %\nСоздано групп: %\nНайдено существующих групп: %\nСвязей ученик-группа создано/подтверждено: %\nПропущено (группа другого центра): %\nОшибок: %',
    v_students_created, v_students_matched, v_groups_created, v_groups_matched, v_links_created, v_skipped_other_center, v_errors;

  if v_skipped_other_center > 0 then
    raise notice E'Группы другого центра (не созданы, как и требовалось):\n%', v_skipped_other_center_list;
  end if;
  if v_errors > 0 then
    raise notice E'Ошибки по отдельным ученикам:\n%', v_error_list;
  end if;
end $$;
